steps.sql:
select left(id::text,8) as group_id, status, driver_id is not null as has_driver
from public.ride_groups where id = 'aaaaaaaa-0000-0000-0000-000000000001';

select event, detail from public.ride_group_events where group_id = 'aaaaaaaa-0000-0000-0000-000000000001';

call public.sp_accept_ride_group(
  'cccccccc-0000-0000-0000-000000000001'::uuid,   -- กลุ่ม C
  '11111111-1111-1111-1111-000000000003'::uuid     -- เป็นผู้โดยสาร ไม่ใช่คนขับ
);

call public.sp_cancel_ride_group(
  'cccccccc-0000-0000-0000-000000000001'::uuid,              -- กลุ่ม C
  '11111111-1111-1111-1111-000000000003'::uuid,               -- ผู้สั่งยกเลิก
  'เปลี่ยนแผนการเดินทาง'         -- เหตุผล
);

select left(id::text,8) as group_id, status, driver_id
from public.ride_groups where id = 'cccccccc-0000-0000-0000-000000000001';

select event, detail from public.ride_group_events where group_id = 'cccccccc-0000-0000-0000-000000000001';

update public.ride_groups
   set created_at = now() - interval '5 hours'
 where id = 'bbbbbbbb-0000-0000-0000-000000000001';

select left(id::text,8) as group_id, status from public.ride_groups where id = 'bbbbbbbb-0000-0000-0000-000000000001';

select e.event, e.detail, left(e.group_id::text,8) as group_id
from public.ride_group_events e order by e.id;
